const r = await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd,numpy as np
from scipy.stats import chi2
D=pd.read_csv('/app/dataset/synthetic_stroke_data.csv'); t=(D.age<0)|(D.age>120)|(D.bmi<10)|(D.bmi>60)|(D.avg_glucose_level<20)|(D.avg_glucose_level>800); V=D.loc[~t].copy(); q1,q3=V.avg_glucose_level.quantile([.25,.75]); h=V.avg_glucose_level>q3+3*(q3-q1); rate=V.groupby('avg_glucose_level').stroke.mean()
sets={}
for name,data,rej in [('all_iqr',V,h),('exact_exception',V,h&(V.avg_glucose_level.map(rate)<.5)),('log2_all',V.assign(avg_glucose_level=np.log2(V.avg_glucose_level)),pd.Series(False,index=V.index)),('no_iqr_raw',V,pd.Series(False,index=V.index))]:
 A=data.loc[~rej].copy(); cols=['age','bmi','avg_glucose_level']; A['risk_proxy']=np.prod(A[cols]/A[cols].max(),axis=1); X=A[cols+['risk_proxy']].to_numpy(); diff=X-X.mean(axis=0); C=np.linalg.pinv(np.cov(X,rowvar=False)); md2=np.einsum('ij,jk,ik->i',diff,C,diff); md=set(A.index[md2>chi2.ppf(.99,4)]); allset=set(D.index[t])|set(V.index[rej])|md; sets[name]=allset; print(name,'iqr',int(rej.sum()),'md',len(md),'total',len(allset),'md_glucose>iqr',len(md&set(V.index[h])),'first20',sorted(allset)[:20]); print('md distribution by row 0-1000 / 1000-3000',sum(i<1000 for i in md),sum(i>=1000 for i in md))
for k,v in sets.items():
 if k!='exact_exception': print('compare exact with',k,'extra',len(v-sets['exact_exception']),'missing',len(sets['exact_exception']-v),'jaccard',len(v&sets['exact_exception'])/len(v|sets['exact_exception']))
